import React, { useCallback, useEffect, useRef, useState } from "react";
import { useHistory } from "react-router-dom";
import { AGENTS } from "./LilAgents";
import "./LilAgentsFlat.css";

// TEST VARIANT — flat-vector companions in the lilagents.xyz visual language:
// tall thin proportions, solid colour blocks, no gradients, no outlines, a
// face reduced to almost nothing, personality carried by the outfit.
//
// Rendered as inline SVG rather than a Lottie file. A Lottie needs an authored
// .json (normally an After Effects export); this paints the same shapes and
// drives the same joints, so it's a fair read on the style. Swapping in a real
// .json later means replacing <FlatAgent> with a Lottie player and keeping the
// walk engine below.
//
// The walk engine is duplicated from LilAgents3D on purpose — this is a
// throwaway comparison and copying ~50 lines beats refactoring a component
// that currently works. Consolidate if this direction wins.

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// ---------------------------------------------------------------------------
// Walk engine (positions in 0..1 across the strip)
// ---------------------------------------------------------------------------
const SPEED = 0.055; // track fractions per second
const MIN_SEP = 0.2;
const STRIDE = 0.032; // track fraction per full leg cycle
const PAUSE = [4.5, 11];
const WALK_SPAN = [0.14, 0.34];
const ACCEL = 0.2;
const DECEL = 0.2;

const clamp01 = (v) => Math.min(Math.max(v, 0), 1);
const lerp = (a, b, t) => a + (b - a) * t;

const travelEase = (t) => {
  const dLin = 1 - ACCEL - DECEL;
  const v = 1 / (ACCEL / 2 + dLin + DECEL / 2);
  if (t <= ACCEL) return (v * t * t) / (2 * ACCEL);
  if (t <= ACCEL + dLin) return (v * ACCEL) / 2 + v * (t - ACCEL);
  const tt = t - ACCEL - dLin;
  return (v * ACCEL) / 2 + v * dLin + v * (tt - (tt * tt) / (2 * DECEL));
};

function planWalk(self, peers, now) {
  if (self.pos > 0.85) self.dir = -1;
  else if (self.pos < 0.15) self.dir = 1;
  else self.dir = Math.random() < 0.5 ? -1 : 1;

  let to = clamp01(
    self.pos + self.dir * lerp(WALK_SPAN[0], WALK_SPAN[1], Math.random())
  );

  for (const other of peers) {
    if (other === self) continue;
    // Clamp against where the peer will END UP, not where it is now. Using its
    // current position lets two idle bots each legally target the same midpoint
    // and walk straight into one another.
    const peerTarget = other.walking ? other.to : other.pos;
    if (self.dir > 0 && peerTarget > self.pos) {
      to = Math.min(to, peerTarget - MIN_SEP);
    } else if (self.dir < 0 && peerTarget < self.pos) {
      to = Math.max(to, peerTarget + MIN_SEP);
    }
  }
  to = clamp01(to);

  if (Math.abs(to - self.pos) < 0.02) {
    self.walking = false;
    self.pauseUntil = now + lerp(PAUSE[0], PAUSE[1], Math.random());
    return;
  }

  self.from = self.pos;
  self.to = to;
  self.duration = Math.max(0.8, Math.abs(to - self.pos) / SPEED);
  self.startedAt = now;
  self.walking = true;
  self.travelled = 0;
  self.facing = to > self.pos ? 1 : -1;
}

// ---------------------------------------------------------------------------
// The character. Flat blocks only — no strokes, no gradients.
// ---------------------------------------------------------------------------
function FlatAgent({ agent, variant }) {
  const skin = "#f7d9c4";
  const dark = "#1e2233";
  const cream = "#f2ede4";

  return (
    <svg className="lilflat-svg" viewBox="0 0 44 108" aria-hidden="true">
      {/* legs — rotated at the hip by JS */}
      <g className="lilflat-leg lilflat-leg-b">
        <rect x="20" y="60" width="7" height="34" fill={cream} />
        <rect x="18" y="92" width="12" height="6" rx="3" fill={dark} />
      </g>
      <g className="lilflat-leg lilflat-leg-a">
        <rect x="15" y="60" width="7" height="34" fill={cream} />
        <rect x="13" y="92" width="12" height="6" rx="3" fill={dark} />
      </g>

      {/* back arm */}
      <g className="lilflat-arm lilflat-arm-b">
        <rect x="26" y="34" width="6" height="28" rx="3" fill={agent.deep} />
      </g>

      {/* torso */}
      <rect x="14" y="32" width="16" height="32" fill={cream} />

      {/* outer layer — the outfit is where the personality lives */}
      {variant === 0 ? (
        // long open jacket
        <>
          <path d="M13 32 h7 v34 h-7 z" fill={agent.mid} />
          <path d="M24 32 h7 v34 h-7 z" fill={agent.mid} />
          <rect x="13" y="32" width="18" height="7" fill={agent.deep} />
          <rect x="15" y="46" width="4" height="5" rx="1" fill={agent.deep} />
          <rect x="25" y="46" width="4" height="5" rx="1" fill={agent.deep} />
        </>
      ) : (
        // buttoned coat + scarf
        <>
          <path d="M13 33 h18 v30 l-4 4 h-10 l-4 -4 z" fill={agent.mid} />
          <rect x="21" y="33" width="2" height="30" fill={agent.deep} />
          <path d="M15 30 h14 v6 h-14 z" fill={agent.hueB} />
          <path d="M26 34 h4 v14 h-4 z" fill={agent.hueB} />
        </>
      )}

      {/* front arm */}
      <g className="lilflat-arm lilflat-arm-a">
        <rect x="12" y="34" width="6" height="28" rx="3" fill={agent.light} />
      </g>

      {/* head — deliberately almost featureless, like the reference */}
      <g className="lilflat-head">
        <rect x="14" y="8" width="16" height="22" rx="7" fill={skin} />
        {variant === 0 ? (
          <>
            {/* cap */}
            <path d="M13 12 a9 9 0 0 1 18 0 v2 h-18 z" fill={dark} />
            <rect x="28" y="13" width="6" height="2" rx="1" fill={dark} />
          </>
        ) : (
          <>
            {/* beanie */}
            <path d="M13 14 a9 9 0 0 1 18 0 v1 h-18 z" fill={agent.hueA} />
            <rect
              x="12"
              y="14"
              width="20"
              height="3"
              rx="1.5"
              fill={agent.hueA}
            />
            {/* round shades */}
            <circle cx="18.5" cy="21" r="3.4" fill={dark} />
            <circle cx="26" cy="21" r="3.4" fill={dark} />
            <rect x="21.4" y="20.4" width="2" height="1.4" fill={dark} />
          </>
        )}
        {/* the whole face: one smile */}
        <path
          d="M19 25 q3 2.6 6 0"
          fill="none"
          stroke={dark}
          strokeWidth="1.2"
          strokeLinecap="round"
        />
      </g>
    </svg>
  );
}

// ---------------------------------------------------------------------------
function LilAgentsFlat() {
  const perchRef = useRef(null);
  const botRefs = useRef([]);
  const [openId, setOpenId] = useState(null);
  const [bubble, setBubble] = useState(null);
  const frozen = prefersReducedMotion();
  const history = useHistory();

  const states = useRef(
    AGENTS.map((_, i) => ({
      pos: i === 0 ? 0.3 : 0.7,
      facing: i === 0 ? 1 : -1,
      dir: i === 0 ? 1 : -1,
      walking: false,
      pauseUntil: 1.5 + i * 3.5,
      startedAt: 0,
      duration: 1,
      from: i === 0 ? 0.3 : 0.7,
      to: i === 0 ? 0.3 : 0.7,
      travelled: 0,
      moved: 0,
      gait: 0,
    }))
  ).current;

  const openIdRef = useRef(null);
  useEffect(() => {
    openIdRef.current = openId;
  }, [openId]);

  useEffect(() => {
    if (frozen) return;
    let raf;
    let last = performance.now();
    const start = last;

    const frame = (now) => {
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;
      const time = (now - start) / 1000;

      states.forEach((st, i) => {
        const el = botRefs.current[i];
        if (!el) return;
        const isOpen = openIdRef.current === AGENTS[i].id;

        if (isOpen) {
          st.walking = false;
          st.pauseUntil = time + 1.5;
        } else if (st.walking) {
          const t = clamp01((time - st.startedAt) / st.duration);
          const prev = st.pos;
          st.pos = lerp(st.from, st.to, travelEase(t));
          st.moved = Math.abs(st.pos - prev);
          st.travelled += st.moved;
          if (t >= 1) {
            st.walking = false;
            st.pauseUntil = time + lerp(PAUSE[0], PAUSE[1], Math.random());
          }
        } else if (time >= st.pauseUntil) {
          planWalk(st, states, time);
        }

        // Per-frame speed, so the stride eases in and out with the accel/decel
        // trapezoid rather than snapping to the walk's average.
        const groundSpeed = st.walking && dt > 0 ? (st.moved || 0) / dt : 0;
        const target = st.walking
          ? Math.min(groundSpeed / (SPEED * 0.35), 1)
          : 0;
        st.gait = lerp(st.gait, target, 0.12);

        const phase = (st.travelled / STRIDE) * Math.PI * 2;
        const swing = Math.sin(phase) * st.gait;

        el.style.left = `${st.pos * 100}%`;
        el.style.setProperty("--flip", st.facing);
        el.style.setProperty(
          "--bob",
          `${Math.abs(Math.sin(phase)) * -2.2 * st.gait}px`
        );
        el.style.setProperty("--legA", `${swing * 22}deg`);
        el.style.setProperty("--legB", `${-swing * 22}deg`);
        el.style.setProperty("--armA", `${-swing * 18}deg`);
        el.style.setProperty("--armB", `${swing * 18}deg`);
        el.style.setProperty("--lean", `${swing * 1.2}deg`);
      });

      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [frozen, states]);

  // Thought bubbles, same cadence as the other variants
  useEffect(() => {
    if (frozen) return;
    let i = 0;
    const tick = () => {
      const agent = AGENTS[i % AGENTS.length];
      setBubble({
        agentId: agent.id,
        text: agent.phrases[Math.floor(Math.random() * agent.phrases.length)],
      });
      i += 1;
      window.setTimeout(() => setBubble(null), 3200);
    };
    const id = window.setInterval(tick, 6500);
    const first = window.setTimeout(tick, 2200);
    return () => {
      window.clearInterval(id);
      window.clearTimeout(first);
    };
  }, [frozen]);

  const toggle = useCallback(
    (id) => setOpenId((cur) => (cur === id ? null : id)),
    []
  );

  useEffect(() => {
    if (!openId) return;
    const onKey = (e) => e.key === "Escape" && setOpenId(null);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [openId]);

  return (
    <div className="pj-agents-perch-flat" ref={perchRef}>
      {AGENTS.map((agent, i) => (
        <div
          key={agent.id}
          className="lilflat-agent"
          ref={(el) => (botRefs.current[i] = el)}
          style={{ left: `${states[i].pos * 100}%` }}
        >
          {bubble && bubble.agentId === agent.id && openId !== agent.id && (
            <div className="lilflat-bubble" role="status">
              {bubble.text}
            </div>
          )}

          {openId === agent.id && (
            <div className="lilflat-popover">
              <div className="lilflat-popover-bar">
                <span className="lilflat-dot lilflat-dot-r" />
                <span className="lilflat-dot lilflat-dot-y" />
                <span className="lilflat-dot lilflat-dot-g" />
                <span className="lilflat-popover-title">
                  {agent.name} · {agent.role}
                </span>
              </div>
              <div className="lilflat-popover-body">
                <p className="lilflat-line lilflat-line-cmd">{agent.cmd}</p>
                {agent.lines.map((line, li) => (
                  <p className="lilflat-line" key={li}>
                    {line}
                  </p>
                ))}
                <a
                  className="lilflat-popover-link"
                  href="/myspace"
                  style={{ color: agent.hueA }}
                  onClick={(e) => {
                    e.preventDefault();
                    history.push("/myspace");
                  }}
                >
                  meet all 9 live tools →
                </a>
              </div>
            </div>
          )}

          <button
            type="button"
            className="lilflat-hit"
            onClick={() => toggle(agent.id)}
            aria-label={`Chat with ${agent.name}, ${agent.role}`}
            aria-expanded={openId === agent.id}
          >
            <FlatAgent agent={agent} variant={i} />
          </button>
        </div>
      ))}
    </div>
  );
}

export default LilAgentsFlat;
